import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

triplet_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor triplet_margin_loss_cuda(torch::Tensor anchor,
                                        torch::Tensor positive,
                                        torch::Tensor negative,
                                        double margin);
"""

triplet_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T, int BLOCK_THREADS>
__global__ void __launch_bounds__(BLOCK_THREADS) triplet_loss_kernel(
    const T* __restrict__ A,
    const T* __restrict__ P,
    const T* __restrict__ N,
    float* __restrict__ out_loss,
    int batch, int dim, float margin, float inv_batch)
{
    int tid = threadIdx.x;
    int dim4 = dim >> 2;                       // number of float4 elements per row
    int elements_per_thread = dim4 / BLOCK_THREADS;
    float block_loss = 0.0f;
    // Grid-stride loop over rows: each block may process multiple rows,
    // accumulating a local partial sum before issuing a single atomicAdd.
    // This drastically reduces atomic contention on out_loss compared to
    // one atomicAdd per row (one per block previously).
    for (int row = blockIdx.x; row < batch; row += gridDim.x) {
        const float4* a4 = reinterpret_cast<const float4*>(A + (size_t)row * dim);
        const float4* p4 = reinterpret_cast<const float4*>(P + (size_t)row * dim);
        const float4* n4 = reinterpret_cast<const float4*>(N + (size_t)row * dim);
        float sum_ap = 0.0f;
        float sum_an = 0.0f;
        #pragma unroll
        for (int i = 0; i < elements_per_thread; ++i) {
            int idx = tid + i * BLOCK_THREADS;
            float4 av4 = a4[idx];
            float4 pv4 = p4[idx];
            float4 nv4 = n4[idx];
            float dap0 = av4.x - pv4.x;
            float dap1 = av4.y - pv4.y;
            float dap2 = av4.z - pv4.z;
            float dap3 = av4.w - pv4.w;
            float dan0 = av4.x - nv4.x;
            float dan1 = av4.y - nv4.y;
            float dan2 = av4.z - nv4.z;
            float dan3 = av4.w - nv4.w;
            sum_ap += dap0 * dap0 + dap1 * dap1 + dap2 * dap2 + dap3 * dap3;
            sum_an += dan0 * dan0 + dan1 * dan1 + dan2 * dan2 + dan3 * dan3;
        }
        // Warp-level reduction
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum_ap += __shfl_down_sync(0xffffffff, sum_ap, offset);
            sum_an += __shfl_down_sync(0xffffffff, sum_an, offset);
        }
        __shared__ float shared_ap[32];
        __shared__ float shared_an[32];
        int lane = tid & 31;
        int wid  = tid >> 5;
        if (lane == 0) {
            shared_ap[wid] = sum_ap;
            shared_an[wid] = sum_an;
        }
        __syncthreads();
        int num_warps = BLOCK_THREADS / 32;
        if (wid == 0) {
            sum_ap = (lane < num_warps) ? shared_ap[lane] : 0.0f;
            sum_an = (lane < num_warps) ? shared_an[lane] : 0.0f;
            #pragma unroll
            for (int offset = 16; offset > 0; offset >>= 1) {
                sum_ap += __shfl_down_sync(0xffffffff, sum_ap, offset);
                sum_an += __shfl_down_sync(0xffffffff, sum_an, offset);
            }
            if (lane == 0) {
                float d_ap = sqrtf(sum_ap);
                float d_an = sqrtf(sum_an);
                float loss = d_ap - d_an + margin;
                loss = loss > 0.0f ? loss : 0.0f;
                block_loss += loss * inv_batch;
            }
        }
        __syncthreads();
    }
    if (tid == 0) {
        atomicAdd(out_loss, block_loss);
    }
}

torch::Tensor triplet_margin_loss_cuda(torch::Tensor anchor,
                                        torch::Tensor positive,
                                        torch::Tensor negative,
                                        double margin) {
    TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
                "All inputs must be CUDA tensors");
    TORCH_CHECK(anchor.dim() == 2 && positive.dim() == 2 && negative.dim() == 2,
                "Inputs must be 2D tensors [batch, dim]");
    TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(),
                "anchor, positive, negative must have the same shape");
    TORCH_CHECK(anchor.scalar_type() == at::kFloat &&
                positive.scalar_type() == at::kFloat &&
                negative.scalar_type() == at::kFloat,
                "Only float32 tensors are supported");

    auto a_c = anchor.contiguous();
    auto p_c = positive.contiguous();
    auto n_c = negative.contiguous();

    int64_t batch = a_c.size(0);
    int64_t dim   = a_c.size(1);

    constexpr int BLOCK_THREADS = 512;
    TORCH_CHECK(dim % (BLOCK_THREADS * 4) == 0,
                "dim must be divisible by BLOCK_THREADS*4 for this vectorized kernel");

    auto out = torch::zeros({}, a_c.options());

    // Dynamically size the grid to match the actual hardware occupancy for
    // this kernel/block configuration, instead of relying on an arbitrary
    // fixed cap. This ensures enough blocks are launched to fully occupy
    // every SM on the current device while still keeping the grid-stride
    // loop so each block accumulates many rows locally before performing a
    // single atomicAdd, which keeps atomic contention on out_loss low.
    int device_id = 0;
    cudaGetDevice(&device_id);
    int sm_count = 1;
    cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device_id);
    int max_active_blocks_per_sm = 1;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &max_active_blocks_per_sm,
        triplet_loss_kernel<float, BLOCK_THREADS>,
        BLOCK_THREADS,
        0);
    int64_t max_blocks = (int64_t)sm_count * (int64_t)std::max(1, max_active_blocks_per_sm);
    int64_t num_blocks = std::min<int64_t>(max_blocks, batch);
    num_blocks = std::max<int64_t>(num_blocks, 1);
    dim3 grid((unsigned)num_blocks);
    dim3 block(BLOCK_THREADS);

    float inv_batch = 1.0f / static_cast<float>(batch);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    triplet_loss_kernel<float, BLOCK_THREADS><<<grid, block, 0, stream>>>(
        a_c.data_ptr<float>(),
        p_c.data_ptr<float>(),
        n_c.data_ptr<float>(),
        out.data_ptr<float>(),
        (int)batch, (int)dim,
        (float)margin, inv_batch
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "triplet_loss_kernel launch failed: ", cudaGetErrorString(err));

    return out;
}
"""

triplet_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=triplet_cpp_decl,
    cuda_sources=triplet_cuda_src,
    functions=["triplet_margin_loss_cuda"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Computes Triplet Margin Loss using a single fused custom CUTE/CUDA kernel.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self._ext = triplet_ext

    def forward(self, anchor: torch.Tensor, positive: torch.Tensor, negative: torch.Tensor) -> torch.Tensor:
        return self._ext.triplet_margin_loss_cuda(anchor, positive, negative, self.margin)

